app.post('/submit', async function(req, res) {
  try {
    var d = req.body;
    if (!d.fullName)          return res.status(400).json({ error: 'الاسم مطلوب' });
    if (!d.phone)             return res.status(400).json({ error: 'رقم الهاتف مطلوب' });
    if (!d.favoritePart)      return res.status(400).json({ error: 'الحقل المطلوب فارغ' });
    if (d.recommendScore == null) return res.status(400).json({ error: 'تقييم التوصية مطلوب' });
    await client.pages.create({
      parent: { database_id: DB_ID },
      properties: {
        'Full Name':                   { title:        [{ text: { content: String(d.fullName) } }] },
        'Phone Number':                { phone_number: String(d.phone) },
        'Clinic Design Rating':        { number: Number(d.clinicDesign) },
        'Cleanliness Rating':          { number: Number(d.cleanliness) },
        'Comfort Rating':              { number: Number(d.comfort) },
        'Reception Rating':            { number: Number(d.reception) },
        'Appointment Rating':          { number: Number(d.appointment) },
        'Doctor Communication Rating': { number: Number(d.doctorComm) },
        'Attention To Detail Rating':  { number: Number(d.attentionToDetail) },
        'Overall Experience Rating':   { number: Number(d.overallExperience) },
        'Favorite Part':               { rich_text: [{ text: { content: String(d.favoritePart) } }] },
        'Improvement Suggestions':     { rich_text: [{ text: { content: String(d.improvements || '') } }] },
        'Recommendation Score':        { number: Number(d.recommendScore) }
      }
    });
    res.json({ success: true });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'حدث خطأ، يرجى المحاولة مجدداً' });
  }
});
